import { LEVELS, SCENARIO, HINTS, SAMPLE_DRAFT, REVISED_DRAFT, inspectWriting, validateSlot, SKILLS, STORY } from './model.mjs';

const icons = {
  home: '<path d="m3 10 9-7 9 7v10H15v-6H9v6H3z"/>',
  compass: '<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5z"/>',
  book: '<path d="M12 5v16M3 4h5a4 4 0 0 1 4 2 4 4 0 0 1 4-2h5v16h-5a4 4 0 0 0-4 1 4 4 0 0 0-4-1H3z"/>',
  path: '<path d="M5 20h10a4 4 0 0 0 0-8H9a4 4 0 0 1 0-8h10"/><circle cx="5" cy="20" r="2"/><path d="m17 2 3 2-3 2"/>',
  badge: '<path d="m12 3 3 2 4 .5.5 4 2 3-2 3-.5 4-4 .5-3 2-3-2-4-.5-.5-4-2-3 2-3 .5-4L9 5z"/><path d="m8 12 3 3 5-6"/>',
  headphones: '<path d="M4 13v-2a8 8 0 0 1 16 0v2M4 12H3v7h4v-7H4Zm16 0h1v7h-4v-7h3Z"/>',
  message: '<path d="M4 4h16v12H9l-5 4z"/><path d="M8 8h8M8 12h5"/>',
  pen: '<path d="m15 4 5 5M4 15l11-11a3.5 3.5 0 0 1 5 5L9 20H4z"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
  play: '<path d="m8 5 11 7-11 7z"/>',
  sound: '<path d="M3 9h4l5-4v14l-5-4H3zM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  spark: '<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',
  calendar: '<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4M16 3v4M4 10h16M8 14h3M8 17h5"/>',
  shield: '<path d="m12 3 8 3v6c0 4-5 7-8 9-3-2-8-5-8-9V6z"/><path d="m8 12 3 3 5-6"/>',
};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.spark}</svg>`;
const esc = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const state = { view: 'today', level: 'a2', language: 'en', step: 'reading', readingAnswer: null, readingChecked: false, transcript: false, listeningAnswer: null, listeningChecked: false, hint: 0, assistance: [], slot: null, slotResult: null, draft: SAMPLE_DRAFT, originalDraft: null, revisions: [], writing: null, revisionSubmitted: false, storyAnswer: null, storyTranslation: false, storyFeedback: false, playing: false };
const workspace = document.querySelector('#workspace');
const support = (en, fa, extra = '') => `${state.language !== 'fa' && en ? `<span class="support-text ${extra}" lang="en">${en}</span>` : ''}${state.language !== 'en' && fa ? `<span class="support-text persian ${extra}" lang="fa" dir="rtl">${fa}</span>` : ''}`;
const phraseButton = (text) => `<button class="audio-button" type="button" data-speak="${esc(text)}" aria-label="Play device voice: ${esc(text)}">${icon('sound')} Luister</button>`;
const actionButton = (action, text, kind = 'primary', attrs = '') => `<button type="button" class="button ${kind}" data-action="${action}" ${attrs}>${text}</button>`;
const level = () => LEVELS.find((item) => item.id === state.level);
const logAssistance = (kind) => { state.assistance.push({ kind, at: new Date().toISOString() }); };
function status(text) { document.querySelector('#a11y-status').textContent = text; }
let toastTimeout;
function toast(text) { const node = document.querySelector('#toast'); node.textContent = text; node.hidden = false; clearTimeout(toastTimeout); toastTimeout = setTimeout(() => { node.hidden = true; }, 5500); }
const demoWarning = () => state.level === 'a2' ? '' : `<div class="level-warning">You are exploring <b>${esc(level().name)}</b>. The interactive mission and story below remain the A2 sample. These targets illustrate the route; this preview does not contain a reviewed course at every level.</div>`;
const head = (eyebrow, title, subtitle, faSubtitle = '') => `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p>${support('', faSubtitle)}</div><span class="date">${icon('calendar')} Design preview · 2026</span></div>`;
const heroArt = `<svg viewBox="0 0 260 260" role="img" aria-label="An illustrated calendar and conversation bubble"><circle cx="146" cy="134" r="97" fill="#dad3eb"/><path d="M68 221c-2-21 8-44 28-48 16-3 30 3 38 11 17-22 40-22 54-4 10 14 12 33 11 48" fill="#c2b7d8"/><g transform="rotate(-8 136 123)"><rect x="60" y="61" width="148" height="139" rx="15" fill="#fbf9ff"/><path d="M60 78c0-10 6-17 15-17h118c9 0 15 7 15 17v15H60" fill="#76658e"/><rect x="83" y="48" width="10" height="28" rx="5" fill="#bcaacc"/><rect x="175" y="48" width="10" height="28" rx="5" fill="#bcaacc"/><g fill="#e2dcea"><rect x="78" y="111" width="22" height="20" rx="5"/><rect x="111" y="111" width="22" height="20" rx="5"/><rect x="144" y="111" width="22" height="20" rx="5"/><rect x="177" y="111" width="15" height="20" rx="5"/><rect x="78" y="146" width="22" height="20" rx="5"/><rect x="111" y="146" width="22" height="20" rx="5"/><rect x="177" y="146" width="15" height="20" rx="5"/></g><rect x="142" y="143" width="26" height="25" rx="7" fill="#44765f"/><path d="m149 155 4 4 8-10" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></g><path d="M25 86a12 12 0 0 1 12-12h62a12 12 0 0 1 12 12v22a12 12 0 0 1-12 12H52l-15 13v-13a12 12 0 0 1-12-12Z" fill="#f6f1df"/><path d="M42 91h51M42 103h34" stroke="#a69870" stroke-width="3" stroke-linecap="round"/><g fill="#bfb5d4"><circle cx="232" cy="59" r="4"/><circle cx="30" cy="187" r="4"/><path d="m217 212 4-8 4 8-4 8Z"/></g></svg>`;
const storyArt = `<svg viewBox="0 0 460 190" role="img" aria-label="An illustrated train window and a forgotten blue bag"><rect x="4" y="27" width="451" height="150" rx="21" fill="#d4dfcc"/><rect x="30" y="42" width="241" height="96" rx="12" fill="#fbfaf0"/><rect x="40" y="51" width="221" height="77" rx="7" fill="#c8dce1"/><path d="M40 100c34-32 53-15 80-33 32-20 55 30 79 17 26-14 39 1 62 9v35H40" fill="#a7c7b6"/><path d="M40 120c27-7 47-12 77-8 33 3 87-5 144 9v7H40" fill="#80a594"/><path d="M142 51v78" stroke="#fbfaf0" stroke-width="7"/><rect x="292" y="103" width="129" height="65" rx="14" fill="#e3c599"/><rect x="307" y="78" width="109" height="51" rx="14" fill="#dfbe8c"/><path d="M303 126h122" stroke="#c5a371" stroke-width="2"/><rect x="327" y="74" width="66" height="75" rx="10" fill="#637ea0"/><path d="M344 78V66a16 16 0 0 1 32 0v12" stroke="#496887" stroke-width="6" fill="none"/><rect x="340" y="105" width="40" height="28" rx="7" fill="#8196b4"/><path d="M64 151h188" stroke="#acc09f" stroke-width="3" stroke-linecap="round"/><circle cx="227" cy="63" r="9" fill="#e5d297"/></svg>`;

function renderToday() {
  return `${head('KLEINE STAPPEN. ECHTE GESPREKKEN.', 'Wat wil je vandaag kunnen?', 'Begin met een doel dat je buiten de les kunt gebruiken.', 'با هدفی شروع کنید که خارج از کلاس بتوانید از آن استفاده کنید.')}${demoWarning()}
  <div class="dashboard-grid"><div><section class="hero"><div class="hero-content"><span class="eyebrow">JOUW OEFENMISSIE · A2 VOORBEELD</span><h2>Een andere afspraak.<br>Een echte oplossing.</h2><p>Je hebt les. Je afspraak moet verplaatst worden. Hoe vind je een tijd die voor iedereen past?</p>${support('', 'کلاس دارید و باید زمان قرار را تغییر دهید. چگونه زمان مناسبی پیدا می‌کنید؟')}${actionButton('start-mission', `Start de oefenmissie ${icon('arrow')}`, 'purple')}</div><div class="hero-art">${heroArt}</div></section>
  <div class="section-heading"><h2>Vier vaardigheden. Eén verhaal.</h2><small>Oefen met samenhang</small></div><div class="skills-grid">${SKILLS.map((skill) => `<button type="button" class="skill-card" data-skill="${skill.id}"><div class="skill-top"><span class="skill-icon ${skill.color}">${icon(skill.icon)}</span><span class="skill-number">${skill.eyebrow}</span></div><h3>${skill.name}</h3>${support(skill.en, skill.fa)}<p>${skill.title}</p><span class="card-arrow">${icon('arrow')}</span></button>`).join('')}</div>
  <div class="learning-strip">${icon('spark')}<div><strong>Vastgelopen? Dat hoort bij leren.</strong><p>Vraag om uitleg, een kleine tip of een voorbeeld — in jouw taal.</p></div>${actionButton('open-help', 'Bekijk taalhulp', 'subtle')}</div></div>
  <aside class="dashboard-side"><section class="panel focus-panel"><div class="focus-header"><span class="eyebrow">MIJN DOEL VANDAAG</span>${icon('compass')}</div><div class="target-statement">“Ik kan mijn afspraak verplaatsen.”</div>${support('I can reschedule my appointment.', 'می‌توانم زمان قرارم را تغییر دهم.')}<ul class="target-list"><li>${icon('check')} Een reden geven</li><li>${icon('check')} Een nieuwe tijd voorstellen</li><li>${icon('check')} De afspraak bevestigen</li></ul><div class="focus-footer"><span class="pill soft"><span class="dot"></span> ${esc(level().name)}</span><span>${esc(level().status)}</span></div></section>
  <section class="panel"><span class="eyebrow">LATER OPNIEUW PROBEREN</span><h3>Onthouden is meer dan herkennen.</h3><div class="review-item"><span class="review-icon">${icon('clock')}</span><div><strong>Dezelfde vaardigheid. Andere situatie.</strong><small>Verplaats een afspraak bij de fietsenmaker.</small></div></div><p class="review-note">This preview schedules a later check; it does not mark a skill as mastered after one successful attempt.</p>${actionButton('review-info', 'Hoe werkt herhalen?', 'subtle')}</section></aside></div>`;
}

function missionNav() {
  return `<aside class="mission-nav"><div class="panel"><span class="eyebrow">A2 VOORBEELDMISSIE</span><h3>Een afspraak verplaatsen</h3>${SKILLS.map((skill, i) => `<button type="button" class="step-button ${state.step === skill.id ? 'active' : ''}" data-step="${skill.id}" ${state.step === skill.id ? 'aria-current="step"' : ''}><span class="step-number">${i + 1}</span>${skill.name}</button>`).join('')}<p class="mini-note">Alle stappen zijn vrij toegankelijk. Deze oefening gebruikt originele, nog niet nagekeken voorbeeldteksten.</p></div><div class="panel mission-progress"><span class="eyebrow">ONDERSTEUNING</span><p>${state.assistance.length ? `${state.assistance.length} help action${state.assistance.length > 1 ? 's' : ''} recorded in this preview. This attempt is assisted.` : 'No hints or transcript revealed yet in this preview.'}</p><p class="caption">Geen cijfer. Wel een eerlijk beeld van je hulp.</p></div></aside>`;
}

function contentHeading(skill, title, description) { return `<div class="content-heading"><div><span class="eyebrow">${SKILLS.find((item) => item.id === skill).eyebrow} · ${skill.toUpperCase()}</span><h2>${title}</h2><p class="caption">${description}</p></div><span class="pill">Original A2 sample</span></div>`; }
function hintBox() { return `<div class="inline-tools">${actionButton('hint', state.hint ? `Volgende tip · ${Math.min(state.hint + 1, 3)} / 3` : 'Een kleine tip', 'small', state.hint >= 3 ? 'disabled' : '')}<span class="hint-count">${state.hint ? `${state.hint} hint${state.hint > 1 ? 's' : ''} used · assisted attempt` : 'Je kiest zelf hoeveel hulp je nodig hebt.'}</span></div>${state.hint ? `<aside class="helper-box"><span class="eyebrow">HULP ${state.hint} / 3</span><p>${HINTS[state.hint - 1].nl}</p>${support(HINTS[state.hint - 1].en, HINTS[state.hint - 1].fa)}</aside>` : ''}`; }
function choices(items, selected, dataName) { return items.map((item) => `<button type="button" class="choice ${selected === item.id ? 'selected' : ''}" data-${dataName}="${item.id}" aria-pressed="${selected === item.id}"><span class="choice-dot" aria-hidden="true"></span><span><b>${item.nl}</b>${support(item.en, item.fa)}</span></button>`).join(''); }

function renderReading() {
  return `${contentHeading('reading', 'Eerst begrijpen. Dan plannen.', 'Lees de herinnering. Wat moet je veranderen?')}<article class="document"><h3>Herinnering aan uw afspraak</h3><p>Beste Sam,</p><p>Uw afspraak bij Tandartspraktijk Molenstraat is op <strong>dinsdag 6 oktober om 10.00 uur</strong>. De afspraak duurt <strong>dertig minuten</strong>.</p><p>Kunt u niet komen? Bel ons om een ander moment af te spreken.</p><p>Met vriendelijke groeten,<br>het team van Tandartspraktijk Molenstraat</p></article><div class="inline-tools">${phraseButton('Uw afspraak is op dinsdag 6 oktober om tien uur. De afspraak duurt dertig minuten.')}${actionButton('reading-translation', 'Vertaal de instructie', 'small')}</div><p class="audio-status">Playback uses an available Dutch voice on your device, if supported. It is not validated Belgian Dutch audio.</p>
  <div class="facts-grid"><div class="fact-card"><span class="eyebrow">JOUW AGENDA</span><strong>Dinsdag · les van 9.00 tot 11.00 uur</strong><p>Je afspraak begint tijdens je les.</p>${support('Your class is from 09:00 to 11:00 on Tuesday.', 'سه‌شنبه از ساعت ۹ تا ۱۱ کلاس دارید.')}</div><div class="fact-card"><span class="eyebrow">JOUW DOEL</span><strong>Een nieuwe afspraak vinden</strong><p>Geef een reden en bevestig de nieuwe tijd.</p>${support('Explain why, then confirm a new time.', 'دلیل را توضیح دهید و زمان جدید را تأیید کنید.')}</div></div>
  <div class="question-block"><h3>Waarom moet je de afspraak verplaatsen?</h3>${choices([{ id: 'class', nl: 'Ik heb dan les.', en: 'I have class then.', fa: 'در آن زمان کلاس دارم.' }, { id: 'closed', nl: 'De praktijk is dinsdag gesloten.', en: 'The practice is closed on Tuesday.', fa: 'مطب سه‌شنبه تعطیل است.' }], state.readingAnswer, 'reading-answer')}</div>
  ${state.readingChecked ? `<div class="feedback-box ${state.readingAnswer === 'class' ? '' : 'warning'}"><strong>${state.readingAnswer === 'class' ? 'Precies. Je les en je afspraak vallen samen.' : 'Kijk nog eens naar je agenda.'}</strong>${state.readingAnswer === 'class' ? 'Nu kun je het probleem kort uitleggen.' : 'De praktijk is open. Je hebt van 9.00 tot 11.00 uur les.'}</div>` : ''}
  <div class="mission-actions">${actionButton('check-reading', 'Controleer mijn antwoord', 'primary', !state.readingAnswer ? 'disabled' : '')}${actionButton('to-listening', 'Verder naar luisteren →', 'subtle')}</div>`;
}

const voicemail = 'Goeiedag Sam, u spreekt met Tandartspraktijk Molenstraat. We herinneren u aan uw afspraak op dinsdag om tien uur. Als u niet kunt komen, bel ons dan om een ander moment af te spreken. Dank u wel.';
function renderListening() {
  return `${contentHeading('listening', 'Een bericht. Wat doe je nu?', 'Luister eerst zonder tekst. Je kunt altijd om hulp vragen.')}<div class="listen-card"><button type="button" class="listen-play" data-speak="${esc(voicemail)}" aria-label="Play sample voicemail using device voice">${icon('play')}</button><div><h3>Voicemail van de praktijk</h3><p>Device voice sample · not Azure audio</p><div class="waveform" aria-hidden="true">${[9,15,23,12,27,19,8,15,26,12,18,27,13,21,10,17,25,12,18,9,16,25,14,7,18,21].map((h) => `<i style="--wave-height:${h}px"></i>`).join('')}</div></div></div><p class="audio-status">A Dutch device voice is required. If unavailable, reveal the transcript to continue; that support is recorded.</p><div class="inline-tools">${actionButton('transcript', state.transcript ? 'Tekst is getoond · hulp geregistreerd' : 'Toon de tekst', 'small', state.transcript ? 'disabled' : '')}</div>${state.transcript ? `<article class="document" style="margin-top:17px"><p>${voicemail}</p>${support('Hello Sam, this is the dental practice. We remind you of your appointment on Tuesday at ten. If you cannot come, call us to arrange another time. Thank you.', 'سلام سام، از مطب دندان‌پزشکی تماس می‌گیریم. قرار شما سه‌شنبه ساعت ده است. اگر نمی‌توانید بیایید، برای تعیین زمان دیگری با ما تماس بگیرید. ممنون.')}</article>` : ''}
  <div class="question-block"><h3>Wat moet je doen als je niet kunt komen?</h3>${choices([{ id: 'call', nl: 'Bellen om een ander moment af te spreken.', en: 'Call to agree on another time.', fa: 'برای توافق درباره زمان جدید تماس بگیرم.' }, { id: 'arrive', nl: 'Toch om tien uur naar de praktijk gaan.', en: 'Still go to the practice at ten.', fa: 'با این حال ساعت ده به مطب بروم.' }], state.listeningAnswer, 'listening-answer')}</div>${state.listeningChecked ? `<div class="feedback-box ${state.listeningAnswer === 'call' ? '' : 'warning'}"><strong>${state.listeningAnswer === 'call' ? 'Goed gehoord. Bellen is de volgende stap.' : 'Luister naar: “Als u niet kunt komen…”'}</strong>${state.listeningAnswer === 'call' ? 'In het gesprek leg je uit waarom je een andere tijd nodig hebt.' : 'De praktijk vraagt je te bellen om een ander moment af te spreken.'}</div>` : ''}
  <div class="mission-actions">${actionButton('check-listening', 'Controleer mijn antwoord', 'primary', !state.listeningAnswer ? 'disabled' : '')}${actionButton('to-speaking', 'Verder naar het gesprek →', 'subtle')}</div>`;
}

function renderSpeaking() {
  return `${contentHeading('speaking', 'Een tijd die écht past.', 'This is a structured conversation simulation. No live agent or microphone assessment.')}<div class="conversation"><div class="bubble"><small>DE RECEPTIONIST</small>Goeiedag, waarmee kan ik u helpen?${phraseButton('Goeiedag, waarmee kan ik u helpen?')}</div><div class="bubble learner"><small>JOUW ANTWOORD</small>Ik wil mijn afspraak verplaatsen. Dinsdag om tien uur kan ik niet, want dan heb ik les.${support('I would like to move my appointment. Tuesday at ten does not work, because I have class then.', 'می‌خواهم زمان قرارم را تغییر دهم. سه‌شنبه ساعت ده نمی‌توانم، چون کلاس دارم.')}${phraseButton('Ik wil mijn afspraak verplaatsen. Dinsdag om tien uur kan ik niet, want dan heb ik les.')}</div><div class="bubble"><small>DE RECEPTIONIST</small>Welke tijd past voor u? De afspraak duurt een halfuur.</div></div><div class="facts-grid"><div class="fact-card"><span class="eyebrow">JOUW WERK</span><strong>Dinsdag · 14.15–15.00 uur</strong><p>Je kunt tijdens je werk niet naar de praktijk.</p></div><div class="fact-card"><span class="eyebrow">OPENINGSUREN</span><strong>Woensdag · 9.00–16.00 uur</strong><p>Je afspraak moet afgelopen zijn voor de praktijk sluit.</p></div></div><div class="question-block"><h3>Stel een moment voor.</h3>${choices(SCENARIO.offers, state.slot, 'slot')}</div>${hintBox()}
  ${state.slotResult ? state.slotResult.valid ? `<div class="feedback-box"><strong>Afgesproken: woensdag 7 oktober, 14.00–14.30 uur.</strong>Deze tijd past in beide agenda’s. Bevestig nu de afspraak in een kort bericht.${support('The code checks the full appointment, not just its start time.', 'کد، کل مدت قرار را بررسی می‌کند، نه فقط زمان شروع آن.')}</div>` : `<div class="feedback-box warning"><strong>${state.slotResult.reason === 'overlap' ? 'Je afspraak zou overlappen met je werk.' : 'De praktijk is dan al gesloten.'}</strong>${state.slotResult.reason === 'overlap' ? 'Om 14.00 uur beginnen betekent om 14.30 uur eindigen. Je werk begint om 14.15 uur.' : 'Een afspraak van 16.00 tot 16.30 uur past niet binnen de openingsuren.'} Probeer een ander moment.</div>` : ''}
  <div class="mission-actions">${actionButton('check-slot', 'Past deze afspraak?', 'primary', !state.slot ? 'disabled' : '')}${actionButton('to-writing', 'Bevestig in een bericht →', 'subtle', !state.slotResult?.valid ? 'disabled' : '')}</div>`;
}

function renderWriting() {
  return `${contentHeading('writing', 'Jij schrijft. Jij verbetert.', 'Illustrative spelling and verb-form rules only. This is not an open-ended writing assessor.')}<div class="feedback-box"><strong>Jouw taak</strong>Bevestig woensdag 7 oktober om 14.00 uur. Gebruik een beleefde begroeting en afsluiting.${support('Confirm Wednesday 7 October at 14:00. Use a polite greeting and closing.', 'چهارشنبه ۷ اکتبر ساعت ۱۴ را تأیید کنید. از سلام و پایان مؤدبانه استفاده کنید.')}</div><div style="margin-top:24px"><label class="textarea-label" for="writing-draft">Mijn bericht</label><textarea id="writing-draft" class="draft" maxlength="1200" spellcheck="false">${esc(state.draft)}</textarea><div class="writing-actions">${actionButton('check-writing', 'Bekijk feedback', 'primary')}${actionButton('sample-writing', 'Bekijk een voorbeeld', 'small')}</div><p class="caption" style="margin-top:11px">Sample text starts with an intentional error. Editing assistance is recorded.</p></div>
  ${state.writing ? `<div class="helper-box"><span class="eyebrow">ÉÉN VERBETERING TEGELIJK</span>${state.writing.issues.length ? state.writing.issues.map((issue) => `<div class="correction"><del>${esc(issue.before)}</del><span aria-hidden="true">→</span><ins>${esc(issue.after)}</ins></div><p>${issue.nl}</p>${support(issue.en, issue.fa)}`).join('') : '<p>De twee voorbeeldregels vinden geen fout. Dat bewijst niet dat de hele tekst correct is.</p>'}${!state.writing.timePresent ? '<p>Noem ook woensdag en 14.00 uur, zodat de afspraak duidelijk is.</p>' : ''}</div><div class="mission-actions">${actionButton('submit-revision', 'Bewaar mijn herziene versie', 'primary')}<span class="caption">Je oorspronkelijke tekst blijft bewaard tijdens deze demo.</span></div>` : ''}
  ${state.revisionSubmitted ? `<div class="feedback-box"><strong>Een bewuste stap vooruit.</strong>Je versie is in deze browserweergave bewaard. ${state.assistance.length ? 'Je gebruikte hulp; dit is ondersteunde oefening.' : 'Er is nog geen hint geregistreerd.'}<details style="margin-top:12px"><summary>Bekijk mijn eerste versie</summary><p>${esc(state.originalDraft || SAMPLE_DRAFT)}</p></details><p>Later: schrijf een bevestiging voor een afspraak bij de fietsenmaker, zonder het voorbeeld. Een andere sessie en minstens vier uur uitstel zijn nodig voordat een onafhankelijke herhaling kan meetellen.</p></div>` : ''}`;
}

function renderMission() { return `${head('EEN PRAKTISCH DOEL. VIER VAARDIGHEDEN.', 'Een afspraak verplaatsen', 'Begrijp het probleem, bespreek een oplossing en bevestig wat je afspreekt.', 'مشکل را بفهمید، راه‌حل پیدا کنید و توافق را تأیید کنید.')}${demoWarning()}<div class="mission-layout">${missionNav()}<section class="mission-content"><div class="panel">${({ reading: renderReading, listening: renderListening, speaking: renderSpeaking, writing: renderWriting })[state.step]()}</div></section></div>`; }

function renderStories() {
  return `${head('KORTE VERHALEN. GROTE ONTDEKKINGEN.', 'Even verdwalen in een verhaal.', 'Lees om iets te begrijpen. Vertel het daarna met je eigen woorden.', 'برای فهمیدن بخوانید. سپس با واژه‌های خودتان بازگو کنید.')}${demoWarning()}<div class="story-layout"><article class="panel"><span class="eyebrow">VERHAALTIJD · A2 VOORBEELD</span><h2 class="story-title">${STORY.title}</h2>${support(STORY.en, STORY.fa)}<div class="story-visual">${storyArt}</div>${STORY.paragraphs.map((paragraph, i) => `<div class="story-paragraph"><p>${paragraph}</p>${state.storyTranslation ? support(STORY.translations.en[i], STORY.translations.fa[i]) : ''}<div class="inline-tools">${phraseButton(paragraph)}</div></div>`).join('')}<div class="inline-tools">${actionButton('story-translation', state.storyTranslation ? 'Vertaling getoond · hulp geregistreerd' : 'Bekijk de vertaling', 'small', state.storyTranslation ? 'disabled' : '')}</div><div class="question-block"><h3>Waarom was de tas belangrijk voor de vrouw?</h3>${choices([{ id: 'photos', nl: 'Haar familiefoto’s zaten in het boek.', en: 'The book contained her family photos.', fa: 'عکس‌های خانواده‌اش داخل کتاب بود.' }, { id: 'ticket', nl: 'Haar treinticket zat in de tas.', en: 'Her train ticket was in the bag.', fa: 'بلیت قطارش داخل کیف بود.' }], state.storyAnswer, 'story-answer')}${actionButton('check-story', 'Controleer', 'primary', !state.storyAnswer ? 'disabled style="margin-top:14px"' : 'style="margin-top:14px"')}</div>${state.storyFeedback ? `<div class="feedback-box ${state.storyAnswer === 'photos' ? '' : 'warning'}"><strong>${state.storyAnswer === 'photos' ? 'Ja. Kijk naar haar laatste bericht.' : 'Lees haar laatste bericht nog eens.'}</strong>“In dat boek staan de foto’s van mijn familie.”</div>` : ''}</article><aside class="story-side"><section class="panel"><span class="eyebrow">WOORDEN IN CONTEXT</span><h3>Herken. Begrijp. Gebruik.</h3><p>Hoor een woord, ontdek het in het verhaal en maak er een eigen zin mee.</p>${[['de tas', 'bag', 'کیف'], ['de trein', 'train', 'قطار'], ['de bladzijde', 'page', 'صفحه'], ['terug', 'back', 'دوباره / پس'], ['het bericht', 'message', 'پیام']].map(([word, en, fa]) => `<div class="word-chip"><span>${word}<small class="support-text">${state.language === 'en' ? en : state.language === 'fa' ? fa : `${en} · ${fa}`}</small></span><button type="button" data-speak="${word}" aria-label="Play ${word}">${icon('sound')}</button></div>`).join('')}</section><section class="panel"><span class="eyebrow">VAN LEZEN NAAR SPREKEN</span><h3>Wat zou jij doen?</h3><p>Je vindt een tas op de trein. Leg aan de treinbegeleider uit waar je de tas hebt gevonden.</p>${support('You find a bag on a train. Explain to the attendant where you found it.', 'در قطار کیفی پیدا می‌کنید. به مأمور توضیح دهید آن را کجا پیدا کرده‌اید.')}<div class="empty-state">Think aloud or practise with someone. This preview does not record or assess your response.</div></section></aside></div>`;
}

function renderPath() {
  return `${head('JOUW ROUTE. JOUW TEMPO.', 'Van je eerste woord tot nuance.', 'Alle leerstappen blijven toegankelijk. Kies waar je wilt verkennen.', 'همه مراحل در دسترس‌اند. مرحله دلخواهتان را انتخاب کنید.')}<div class="path-grid">${LEVELS.map((item) => `<button type="button" class="level-card ${state.level === item.id ? 'current' : ''}" data-level="${item.id}" aria-pressed="${state.level === item.id}"><span class="level-name">${item.name}</span><p>${item.nl}</p><small>${item.status}</small><span class="tag-row">${SKILLS.map((skill) => `<span class="mini-tag">${skill.name}</span>`).join('')}</span></button>`).join('')}</div><aside class="panel path-explainer"><h3>Een brug is geen nieuw officieel niveau.</h3><p>Pre-A2, Pre-B1, Pre-B2, Pre-C1 and Pre-C2 are internal transition stages. A1–C2 are CEFR levels; Pre-A1 also appears as a descriptor band in the CEFR Companion Volume. This demonstration contains one original A2 mission and one story, not a complete course or a validated proficiency test.</p></aside>`;
}

function renderExam() {
  return `${head('VOORBEREIDEN MET EEN DUIDELIJK DOEL.', 'Kies een examen. Begrijp de taak.', 'Gebruik de officiële informatie als uitgangspunt voor je voorbereiding.', 'آمادگی خود را بر اساس اطلاعات رسمی آزمون برنامه‌ریزی کنید.')}<div class="exam-grid"><section class="panel exam-card"><span class="eyebrow">OFFICIËLE EXAMENINFORMATIE</span><h2>CNaVT</h2><p>Dutch certificates organised around language-use profiles. EDUP is a preparation direction; this app does not award a CNaVT certificate.</p><ul><li>Start with the official profile and current requirements.</li><li>Practise original tasks, without copying protected exam items.</li><li>Keep writing, reading, speaking and listening evidence separate.</li></ul><a class="official-link" href="https://www.cll.be/nl/volwassenen/officiele-examens/nederlandse-test-cnavt/" target="_blank" rel="noopener noreferrer">Bekijk de officiële CNaVT-website ↗</a></section><section class="panel exam-card"><span class="eyebrow">OFFICIËLE EXAMENINFORMATIE</span><h2>ITNA</h2><p>A Dutch test used in academic contexts. Check the receiving institution’s current admission rules and accepted results.</p><ul><li>Read the official test format before selecting practice.</li><li>Work on understanding instructions and communicating clearly.</li><li>Use practice evidence as preparation, not an admission guarantee.</li></ul><a class="official-link" href="https://www.itna.be/over-de-test/testonderdelen/testonderdelen-b2/" target="_blank" rel="noopener noreferrer">Bekijk de officiële ITNA-website ↗</a></section></div><div class="ownership-note">${icon('shield')}<div><strong>No invented pass mark.</strong><p>Exam dates, fees and admission policies can change. The official provider and receiving university determine acceptance. This preview displays no readiness percentage, certificate or claimed exam result.</p></div></div>`;
}

function render() {
  document.querySelector('#level-select').value = state.level;
  document.querySelector('#language-select').value = state.language;
  const titles = { today: 'Vandaag', mission: 'Oefenmissie', stories: 'Verhaaltijd', path: 'Mijn leerroute', exam: 'Examenwijzer' };
  document.querySelector('#breadcrumb-title').textContent = titles[state.view];
  document.querySelectorAll('[data-view]').forEach((node) => { const active = node.dataset.view === state.view; node.classList.toggle('active', active); if (active) node.setAttribute('aria-current', 'page'); else node.removeAttribute('aria-current'); });
  workspace.innerHTML = ({ today: renderToday, mission: renderMission, stories: renderStories, path: renderPath, exam: renderExam })[state.view]();
}
function navigate(view) { state.view = view; render(); workspace.focus({ preventScroll: true }); window.scrollTo({ top: 0, behavior: 'auto' }); }
function speak(text) {
  if (!('speechSynthesis' in window)) { toast('Your browser does not support device speech. Read the text or use your device’s accessibility tools.'); return; }
  const voices = window.speechSynthesis.getVoices();
  const voice = voices.find((item) => /^nl[-_]BE$/i.test(item.lang)) || voices.find((item) => /^nl(?:[-_]|$)/i.test(item.lang));
  if (!voice) { toast('No Dutch device voice is available. Audio in the Azure application requires a verified Speech integration.'); return; }
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text); utterance.voice = voice; utterance.lang = voice.lang; utterance.rate = 0.88;
  utterance.onerror = () => toast('Device playback did not finish. You can continue with the displayed text.');
  window.speechSynthesis.speak(utterance);
  status('Playing device-generated Dutch audio. Not a pronunciation assessment.');
}

document.querySelector('#level-select').innerHTML = LEVELS.map((item) => `<option value="${item.id}">${item.name}</option>`).join('');
document.querySelectorAll('[data-icon]').forEach((node) => { node.innerHTML = icon(node.dataset.icon); });
document.querySelector('#level-select').addEventListener('change', (event) => { state.level = event.target.value; render(); status(`Learning stage ${level().name}. Interactive content remains the A2 sample.`); });
document.querySelector('#language-select').addEventListener('change', (event) => { state.language = event.target.value; render(); status('Language support updated.'); });
document.querySelector('#reset-demo').addEventListener('click', () => { window.location.reload(); });
document.addEventListener('input', (event) => { if (event.target.id === 'writing-draft') { state.draft = event.target.value; state.revisionSubmitted = false; } });
document.addEventListener('click', (event) => {
  const button = event.target.closest('button'); if (!button || button.disabled) return;
  if (button.dataset.view) return navigate(button.dataset.view);
  if (button.dataset.speak) return speak(button.dataset.speak);
  if (button.dataset.level) { state.level = button.dataset.level; render(); return status(`Selected ${level().name}.`); }
  if (button.dataset.skill) { state.step = button.dataset.skill; return navigate('mission'); }
  if (button.dataset.step) { state.step = button.dataset.step; render(); return; }
  if (button.dataset.readingAnswer) { state.readingAnswer = button.dataset.readingAnswer; state.readingChecked = false; render(); return; }
  if (button.dataset.listeningAnswer) { state.listeningAnswer = button.dataset.listeningAnswer; state.listeningChecked = false; render(); return; }
  if (button.dataset.slot) { state.slot = button.dataset.slot; state.slotResult = null; render(); return; }
  if (button.dataset.storyAnswer) { state.storyAnswer = button.dataset.storyAnswer; state.storyFeedback = false; render(); return; }
  const action = button.dataset.action;
  if (action === 'open-help') return document.querySelector('#help-dialog').showModal();
  if (action === 'close-help') return document.querySelector('#help-dialog').close();
  if (action === 'start-mission') { state.step = 'reading'; return navigate('mission'); }
  if (action === 'review-info') return toast('A later check uses a different situation, a new session and no hints. This demo does not simulate elapsed time or claim mastery.');
  if (action === 'reading-translation') { logAssistance('instruction-translation'); render(); return toast(state.language === 'en' ? 'Read the reminder. You have class on Tuesday from 09:00 to 11:00. Why must you move the appointment? Support recorded.' : 'یادآوری قرار را بخوانید. سه‌شنبه از ۹ تا ۱۱ کلاس دارید. چرا باید زمان قرار را تغییر دهید؟ کمک ثبت شد.'); }
  if (action === 'check-reading') state.readingChecked = true;
  if (action === 'to-listening') state.step = 'listening';
  if (action === 'transcript') { state.transcript = true; logAssistance('listening-transcript'); }
  if (action === 'check-listening') state.listeningChecked = true;
  if (action === 'to-speaking') state.step = 'speaking';
  if (action === 'hint' && state.hint < 3) { state.hint += 1; logAssistance(`hint-${state.hint}`); }
  if (action === 'check-slot') { state.slotResult = validateSlot(state.slot); status(state.slotResult.valid ? 'The appointment fits both calendars.' : 'The appointment conflicts with the calendar or opening hours.'); }
  if (action === 'to-writing') state.step = 'writing';
  if (action === 'check-writing') { state.originalDraft ??= state.draft; state.writing = inspectWriting(state.draft); logAssistance('writing-demo-feedback'); status('Illustrative writing feedback is ready.'); }
  if (action === 'sample-writing') { logAssistance('writing-example'); toast(REVISED_DRAFT); }
  if (action === 'submit-revision') { state.writing = inspectWriting(state.draft); if (state.writing.issues.length || !state.writing.timePresent) return toast('Revise the highlighted verb form and include Wednesday at 14:00. Your draft is kept.'); state.revisions.push({ draft: state.draft, at: new Date().toISOString(), assisted: state.assistance.length > 0 }); state.revisionSubmitted = true; status('Revised version kept in this preview. Assisted practice, not mastery.'); }
  if (action === 'story-translation') { state.storyTranslation = true; logAssistance('story-translation'); }
  if (action === 'check-story') state.storyFeedback = true;
  render();
});
// Ask the device to load its voice inventory without starting playback.
if ('speechSynthesis' in window) window.speechSynthesis.getVoices();
render();
